class WorkOrders(BaseModel):
    today_count: conint(ge=0) | None = Field(None, description='今日新建工單數')
    completion_rate: confloat(ge=0.0, le=1.0) | None = Field(
        None,
        description='今日完工率 = 今日完工 / 今日新建（today_count == 0 時為 null）',
    )
    overdue_count: conint(ge=0) | None = Field(
        None,
        description='排程時間已過且未結案（status NOT IN completed/closed/cancelled）',
    )


class Technicians(BaseModel):
    total_count: conint(ge=0) | None = Field(
        None, description="此租戶啟用中（status='active'）的技師總數"
    )
    online_count: conint(ge=0) | None = Field(
        None, description='目前可派遣的技師數（active 且不在執行中工單）'
    )
    dispatchable_count: conint(ge=0) | None = Field(
        None, description='已上線且可立即指派（保留欄位，目前等同 online_count）'
    )


class DashboardStats(BaseModel):
    period: DashboardPeriod
    conversations: Conversations
